#pragma once

#include <cstddef>
#include <cstdint>
#include <functional>
#include <optional>
#include <vector>

// Translation between the Address Library ID spaces of SkyrimSE 1.6.x (AE) and
// SkyrimSE 1.5.97 (SE).
//
// The client sources reference AE IDs everywhere (`POINTER_SKYRIMSE(..., 38936)`).
// Address Library IDs are version specific, so on 1.5.97 every one of those IDs
// has to be translated before it is looked up. The table in
// SkyrimIdMap1597.inl is generated by tools/port1597/gen_inl.py from the Phase 0
// reversal (docs/phase0/id_map_1_5_97.csv).
//
// Entries with a zero SE id are *known* but not reversed yet: the client keeps
// running and the startup audit prints the complete list of what is missing.
namespace AddressLibrary
{
struct IdMapping
{
    std::uint32_t aeId{0};
    std::uint32_t seId{0}; // 0 == not reversed yet
};

struct IdMapStats
{
    std::size_t total{0};
    std::size_t mapped{0};
};

const IdMapping* GetIdMappings1597(std::size_t& aCount) noexcept;
IdMapStats GetIdMap1597Stats() noexcept;

// Returns the 1.5.97 id for an AE id, or nullopt when there is no known
// mapping (caller should treat the id as unresolved).
std::optional<std::uint32_t> TranslateAeToSe1597(std::uint64_t aAeId) noexcept;

bool IsKnownAeId1597(std::uint64_t aAeId) noexcept;

struct AuditReport
{
    std::size_t total{0};
    std::size_t resolved{0};
    std::vector<std::uint32_t> unresolved;
    std::vector<std::uint32_t> unknown; // referenced by code but absent from the table
};

// Resolves every AE id the client links against. `aIsResolved` receives the id
// that will actually be looked up (already translated) and must answer whether
// the loaded database can resolve it.
AuditReport AuditIds1597(const std::function<bool(std::uint32_t)>& aIsResolved);
} // namespace AddressLibrary
